<script setup>
import { computed, onUnmounted, reactive, ref, toRefs, watch } from 'vue'
import Icon from './GardenIcon.vue'
import Cover from './NativeCover.vue'
import Sheet from './GardenSheet.vue'
import WorkshopActivity from './WorkshopActivity.vue'
import { cap, sizeText, shortDate } from './nativeModel.js'
import { downloadLabel, subscriptionLabel, updateEligible } from './workshopRuntime.js'
import { createWorkshopCatalogRuntime, catalogStatusView } from './workshopCatalogRuntime.js'
import { createWorkshopTranslationRuntime } from './workshopTranslationRuntime.js'
const props=defineProps({bridge:Object,installation:Object,active:Boolean,mods:{type:Array,default:()=>[]},steam:Object,steamState:Object,aiRevision:Number})
const emit=defineEmits(['import','reveal','refresh-mods','ai-settings','logs'])
const query=ref(''),chip=ref('hot'),page=ref(1),pageSize=ref(24),notice=ref(''),imageUrl=ref(''),unsubscribeTarget=ref(null)
const catalogState=reactive({}),catalog=createWorkshopCatalogRuntime(props.bridge,catalogState)
const {result,selected,listLoading,detailLoading,error}=toRefs(catalogState)
const busy=computed(()=>listLoading.value||detailLoading.value)
const translation=reactive({}),translator=createWorkshopTranslationRuntime(props.bridge,translation)
let searchTimer
const installedMod=computed(()=>props.mods.find(m=>m.workshop_id===selected.value?.workshop_id))
const localFor=item=>props.steam?.items()[item?.workshop_id]||item?.local
const selectedLocal=computed(()=>localFor(selected.value))
const downloads=computed(()=>(props.steamState?.status?.items||[]).filter(x=>['downloading','download_pending'].includes(x.download_state)))
const capabilities=computed(()=>props.steamState?.status?.capabilities || result.value?.capabilities || {})
const connection=computed(()=>props.steam?.statusView()||{title:'正在读取工坊状态',message:'正在核对游戏安装和 Steam 会话。',refreshLabel:'刷新连接'})
const catalogStatus=computed(()=>catalogStatusView(result.value,{pollingPaused:catalogState.listPollingPaused}))
const payload=()=>props.installation?{installation_id:props.installation.installation_id}:{}
const number=n=>n==null?'未知':Number(n).toLocaleString('zh-CN')
const translatedTitle=computed(()=>translation.show&&translator.text('title')||selected.value?.title)
const translatedDescription=computed(()=>translation.show&&translator.text('description')||selected.value?.description)
async function browse(refresh=false){return catalog.browse({query:query.value,page:page.value,page_size:pageSize.value,sort:chip.value,refresh})}
async function detail(item,refresh=false){const id=typeof item==='string'?item:item.workshop_id;void translator.select(id,props.installation?.installation_id);await catalog.select(item,refresh);if(translation.workshopId===id)void translator.hydrateCache()}
async function open(intent='workshop',id){error.value='';try{const r=await props.bridge.request('workshop.open',{...(id?{workshop_id:id}:{}),intent,target:'steam'});notice.value=r.message||'已打开 Steam 官方页面。'}catch(e){error.value=e.message}}
async function act(action,item=selected.value){const id=item?.workshop_id;if(!id)return;const r=await props.steam?.act(action,[id]);if(r)unsubscribeTarget.value=null}
function back(){catalog.back();void translator.select(null)}
function resizePage(){page.value=1;back();void browse()}
function search(value){clearTimeout(searchTimer);query.value=value||'';page.value=1;back();void browse()}
function changeChip(value){clearTimeout(searchTimer);chip.value=value;page.value=1;back();void browse()}
function queryChanged(){clearTimeout(searchTimer);searchTimer=setTimeout(()=>{page.value=1;void browse()},450)}
watch(()=>props.installation?.installation_id,id=>{catalog.setInstallation(id);void translator.select(null,id);if(props.active)void browse()},{immediate:true})
watch(()=>props.active,value=>{if(value&&!result.value&&!listLoading.value)void browse()},{immediate:true})
watch(()=>props.aiRevision,()=>translator.invalidate())
watch(()=>[selected.value?.workshop_id,selected.value?.source_updated_at,selected.value?.source_pending],()=>{if(selected.value&&!selected.value.source_pending&&translation.workshopId===selected.value.workshop_id)void translator.hydrateCache()})
onUnmounted(()=>{clearTimeout(searchTimer);translator.dispose();catalog.dispose()})

defineExpose({search})
</script>
<template>
  <div class="formal-ui"><section class="page on scroll" data-testid="workshop-panel" :aria-busy="busy">
    <div class="garden-intro"><div><h1>创意工坊</h1><p>浏览、订阅和更新 Probably Stolen 模组；下载完成后，在模组页整理启用顺序。</p></div><div class="garden-intro-actions"><button class="garden-btn soft sm" @click="open()"><Icon name="steam" size="sm"/>Steam 官方页面</button></div></div>
    <div class="garden-card ws-howto" data-testid="workshop-connection-status"><div class="grow"><h2>{{ connection.title }}</h2><p>{{ connection.message }}<span v-if="connection.retained"> 订阅与下载信息保留上次读取的记录。</span></p><details><summary>账号与匿名访问</summary><p>使用 Steam 客户端当前账号直接订阅、取消订阅和下载更新；订阅回调确认与文件下载分开核对。{{ capabilities.anonymous_download?.reason || '匿名访问只用于公开浏览，不代表已登录账号或可以下载本游戏内容。' }}</p></details></div><button v-if="connection.action==='logs'" class="garden-btn sm" @click="emit('logs')">{{ connection.actionLabel }}</button><button class="garden-btn sm" data-testid="workshop-refresh-status" :disabled="steamState?.loading" @click="steam?.refresh(true)">{{ connection.refreshLabel }}</button><button class="garden-btn sm" @click="emit('import')">导入本地包</button></div>
    <div v-if="error" class="care-note" role="alert">{{ error }} <button class="garden-link" @click="browse(true)">重试列表</button></div><div v-if="notice" class="garden-notice" role="status">{{ notice }}<button class="garden-link" @click="notice=''">关闭</button></div><div v-if="catalogStatus" data-testid="workshop-catalog-status" :class="catalogStatus.kind==='error'?'care-note':'mint-note'" :role="catalogStatus.kind==='error'?'alert':'status'">{{ catalogStatus.text }}<button v-if="catalogStatus.retry" class="garden-link" @click="browse(true)">刷新列表</button></div>
    <WorkshopActivity :state="steamState" :mods="mods" :show-error="steamState?.error!==connection.message"/>
    <template v-if="selected">
      <div class="workshop-detail-nav"><button class="garden-link" style="color:var(--g-text-2);margin:2px 0 14px" @click="back"><Icon name="left" size="sm"/>返回列表</button><span v-if="detailLoading" class="muted" role="status">正在补全详情…</span><span v-else-if="selected.stale" class="muted">缓存详情 · 正在后台更新</span><button class="garden-link" :disabled="detailLoading" @click="detail(selected,true)">刷新详情</button></div>
      <div class="garden-card ws-detail-hero">
        <div class="ws-cover"><Cover :bridge="bridge" :workshop-id="selected.workshop_id" :refresh-key="selected.source_updated_at" :src="selected.preview_url" :title="selected.title" zoom @open="imageUrl=$event"/></div>
        <div><div class="d-tags" style="margin:0"><span class="tg on">{{ selected.tags?.[0] || '创意工坊' }}</span><span v-if="installedMod?.version" class="tg off">本机 v{{ installedMod.version }}</span><span class="tg" :class="selectedLocal?.subscription_state==='subscribed'?'on':'off'">{{ subscriptionLabel(selectedLocal) }}</span><span class="tg" :class="downloadLabel(selectedLocal).tone">{{ downloadLabel(selectedLocal).text }}</span></div><h1>{{ translatedTitle }}</h1><div v-if="translation.show&&translator.text('title')" class="muted">{{ selected.title }}</div><div class="d-by">{{ selected.author || '作者未公开' }}</div>
          <div class="stats"><div class="stat"><small>订阅</small><b>{{ number(selected.subscriptions) }}</b></div><div class="stat"><small>评分</small><b>{{ selected.rating == null?'未知':selected.rating }}</b></div><div class="stat"><small>更新</small><b>{{ shortDate(selected.time_updated) }}</b></div><div class="stat"><small>大小</small><b>{{ sizeText(selected.file_size) }}</b></div></div>
          <div class="d-actions" style="margin-top:16px"><button v-if="installedMod" class="garden-btn" @click="emit('reveal',installedMod.id)">在模组页查看</button><button v-if="selectedLocal?.subscription_state!=='subscribed'" data-testid="workshop-subscribe" class="garden-btn green" :disabled="!steam?.available('subscribe')" :title="steam?.reason('subscribe')" @click="act('subscribe')"><Icon name="steam" size="sm"/>订阅</button><button v-else data-testid="workshop-unsubscribe" class="garden-btn clay" :disabled="!steam?.available('unsubscribe')" @click="unsubscribeTarget=selected">取消订阅…</button><button data-testid="workshop-update" class="garden-btn green" :disabled="!updateEligible(selectedLocal)||!steam?.available('update')" @click="act('update')">更新</button><button class="garden-btn soft" @click="open('detail',selected.workshop_id)">官方页面</button></div>
        </div>
      </div>
      <div class="ws-cols"><div class="garden-card"><h2>介绍</h2>
        <div class="translation-bar"><template v-if="translation.status==='running'"><span>AI 正在翻译 {{ translation.total?`${translation.done} / ${translation.total} 段`:'…' }}</span><button class="garden-link" @click="translator.cancel">停止</button></template><button v-else data-testid="workshop-translate" class="garden-btn sm" :disabled="translation.cacheLoading" @click="translator.translate(installation?.installation_id,translation.status!=='idle')">{{ translation.cacheLoading?'检查已有译文…':translation.status==='idle'?'AI 翻译为中文':'重新翻译' }}</button><button v-if="translator.text('description')||translator.text('title')" data-testid="workshop-translation-toggle" class="garden-link" @click="translation.show=!translation.show">{{ translation.show?'查看原文':'查看译文' }}</button></div>
        <div v-if="translation.error" class="care-note">{{ translation.error }} <button class="garden-link" @click="emit('ai-settings')">前往设置配置 AI</button></div><p v-if="translation.status==='cancelled'" class="muted">翻译已停止，原文仍保留。</p><p v-if="translation.show&&(translator.text('description')||translator.text('title'))" class="translation-note">AI 译文 · 可随时切回原文。{{ translation.cached?'已复用缓存译文。':'' }}{{ translation.truncated?'介绍较长，仅翻译了前面部分。':'' }}</p><div v-if="detailLoading&&!selected.description" class="detail-skeleton" aria-label="详情正在加载"><i></i><i></i><i></i></div><div v-else class="desc">{{ translatedDescription || '未取得公开介绍，可在官方页面查看。' }}</div>
      </div><div style="display:flex;flex-direction:column;gap:16px"><div class="garden-card"><h2><Icon name="git"/>必需条目</h2><div class="lst" style="margin-top:8px"><div v-for="item in selected.required_items" :key="item.workshop_id || item" class="li"><div class="ln"><b>{{ item.title || item.workshop_id || item }}</b></div><button class="garden-link" @click="detail(String(item.workshop_id || item))">查看</button></div><span v-if="!selected.required_items?.length" class="muted">{{ selected.children_kind==='unknown'?'没有可核实的必需条目信息。':'工坊页面没有列出必需条目。' }}</span></div></div><div class="garden-card"><h2><Icon name="shield"/>权限</h2><div v-if="installedMod?.capabilities?.length" class="perm-chips"><span v-for="c in installedMod.capabilities" :key="c" class="perm-chip" :class="cap(c).level"><Icon :name="cap(c).icon" size="xs"/>{{ cap(c).label }}</span></div><p v-else class="muted">{{ installedMod?'本机包未声明额外权限。':'下载后读取 manifest.xml 才能确定。' }}</p><button v-if="installedMod" class="garden-link" @click="emit('reveal',installedMod.id,'perm')">查看本机启用同意与权限</button></div></div></div>
    </template>
    <template v-else>
      <div class="ws-toolbar"><div class="garden-chips"><button v-for="[key,label] in [['hot','最热门'],['recent','最近更新'],['new','最新发布'],['mine','我的订阅']]" :key="key" :class="{on:chip===key}" @click="changeChip(key)">{{ label }}</button></div><label class="garden-search"><Icon name="search" size="sm"/><input v-model="query" placeholder="搜索创意工坊" @input="queryChanged" @keydown.enter="search(query)"/></label><label class="page-size">每页<select v-model.number="pageSize" data-testid="workshop-page-size" @change="resizePage"><option :value="12">12</option><option :value="24">24</option><option :value="48">48</option></select>项</label><button class="garden-btn sm" style="margin-left:auto" :disabled="detailLoading" @click="browse(true)">刷新</button></div>
      <div v-if="chip==='mine'&&steamState?.status?.session?.state!=='ready'" class="mint-note">Steam 会话未就绪，当前只显示本机内容记录，不能据此确认账号订阅。</div>
      <div v-for="download in downloads" :key="download.workshop_id" class="garden-card queue-card" style="padding:12px 18px;margin-bottom:16px"><Icon name="download"/><b>{{ downloadLabel(download).text }}</b><span>{{ download.title || download.workshop_id }}</span><div v-if="download.progress != null" class="garden-solar"><i :style="{width:Math.round(download.progress*100)+'%'}"></i></div><span>{{ download.progress==null?'进度未知':Math.round(download.progress*100)+'%' }}</span><span class="muted">由 Steam 下载</span></div>
      <div class="ws-grid"><article v-for="item in result?.items || []" :key="item.workshop_id" class="ws-card"><button class="ws-card-main" @click="detail(item)"><div class="ws-cover"><Cover :bridge="bridge" :workshop-id="item.workshop_id" :refresh-key="item.source_updated_at" :src="item.preview_url" :title="item.title" lazy/><span class="tg dark tl">{{ item.tags?.[0] || '创意工坊' }}</span><span v-if="localFor(item)?.mod_version" class="tg ghost tr">本机 v{{ localFor(item).mod_version }}</span><span v-if="localFor(item)" class="bl"><span class="tg" :class="downloadLabel(localFor(item)).tone">{{ subscriptionLabel(localFor(item)) }} · {{ downloadLabel(localFor(item)).text }}</span></span></div><div class="ws-body"><b>{{ item.title }}</b><small>{{ item.author || '作者未公开' }} · {{ item.rating==null?'评分未知':'★ '+item.rating }} · {{ number(item.subscriptions) }} 订阅</small><p>{{ item.description }}</p></div></button><div class="ws-card-actions"><button v-if="localFor(item)?.subscription_state==='subscribed'" class="garden-btn clay xs" :data-testid="'card-unsubscribe-'+item.workshop_id" :disabled="!steam?.available('unsubscribe')" :title="steam?.reason('unsubscribe')" @click="unsubscribeTarget=item">取消订阅</button><button v-else class="garden-btn green xs" :data-testid="'card-subscribe-'+item.workshop_id" :disabled="!steam?.available('subscribe')" :title="steam?.reason('subscribe')" @click="act('subscribe',item)">订阅</button><button class="garden-btn xs" :data-testid="'card-update-'+item.workshop_id" :disabled="!updateEligible(localFor(item))||!steam?.available('update')" :title="!updateEligible(localFor(item))?'没有可更新的文件':steam?.reason('update')" @click="act('update',item)">更新</button><button class="garden-link" @click="detail(item)">详情</button></div></article></div>
      <div v-if="listLoading&&!result?.items?.length" class="garden-empty" role="status">正在读取 Steam 创意工坊…</div><div v-else-if="result&&!result.items?.length&&!result.network_error&&!result.loading" class="garden-empty">没有找到匹配条目。可以调整搜索，或在官方页面查找。</div><div v-if="result && (page>1||result.has_more)" class="workshop-pages"><button class="garden-btn sm" :disabled="page<=1||busy" @click="page--;browse()">上一页</button><span>第 {{ page }} 页</span><button class="garden-btn sm" :disabled="!result.has_more||busy" @click="page++;browse()">下一页</button></div>
    </template>
    <Sheet v-if="imageUrl" :title="selected?.title||'完整封面'" wide @close="imageUrl=''"><div class="full-cover"><Cover :src="imageUrl" :title="selected?.title"/></div></Sheet>
    <Sheet v-if="unsubscribeTarget" title="取消订阅" :busy="steamState?.pending" @close="unsubscribeTarget=null"><p>{{ unsubscribeTarget?.title }}</p><div class="sign-note">Steam 可能移除本机包文件；管理器不会清除模组配置、存档或你的启用草稿。</div><p v-if="steamState?.error" class="care-note">{{ steamState.error }}</p><template #footer><span class="sp"></span><button class="garden-btn sm" :disabled="steamState?.pending" @click="unsubscribeTarget=null">保留订阅</button><button class="garden-btn clay sm" data-testid="workshop-unsubscribe-confirm" :disabled="!steam?.available('unsubscribe')" @click="act('unsubscribe',unsubscribeTarget)">确认取消订阅</button></template></Sheet>
  </section></div>
</template>
